INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 8, 'theory', 'Quiz: INSERT, UPDATE, DELETE');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 8, 0, 'What happens when you run UPDATE products SET price = 0; without WHERE?', '["Nothing: SQLite requires WHERE", "The price becomes 0 in every row of the table", "Only the first row is updated", "A syntax error"]', 1, 'Without WHERE all rows are affected. Before changing, it helps to run a SELECT with the same condition and check the row count.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 8, 1, 'How do you insert three rows with one command?', '["Write VALUES three times in a row without commas", "List three sets of values separated by commas in one VALUES", "Use UPDATE with three SETs", "It''s impossible"]', 1, 'INSERT INTO t (a, b) VALUES (1, 2), (3, 4), (5, 6) adds all the rows in one command; on an error none is added.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 8, 2, 'What is a transaction for?', '["To speed up SELECT", "To run several commands as one whole: all or none", "To drop a table", "To sort rows"]', 1, 'COMMIT makes the changes of the whole transaction permanent, ROLLBACK cancels everything done since its start.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 8, 3, 'What does INSERT … ON CONFLICT (id) DO UPDATE SET … do?', '["Always inserts a second row with the same id", "If a row with this id already exists, updates it, otherwise inserts", "Deletes the conflicting row", "Rolls back the transaction"]', 1, 'This is an UPSERT: when uniqueness on the specified key is violated, an update runs instead of an error.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 8, 4, 'How do you find out the ID that a just-inserted row received?', '["Run SELECT MAX(id)", "Add RETURNING id to the INSERT", "Run an UPDATE", "You can''t find out the ID"]', 1, 'RETURNING gives back the values of the inserted (or changed/deleted) row right from the command; MAX(id) is unreliable with concurrent inserts.');
